// ── Date formatter ─────────────────────────────────────
function formatDate(date) {
  const d = new Date(date);
  if (isNaN(d)) return '';
  return String(d.getDate()).padStart(2,'0') + '/' +
         String(d.getMonth()+1).padStart(2,'0') + '/' +
         d.getFullYear();
}

const fileData = $('Watch Contracts Folder').first().json;
const extractedData = $input.first().json;

// Get contract text
const contractText = extractedData.text || extractedData.content || '';

// Truncate to 12000 chars to stay within token limits
const truncatedText = contractText.length > 12000
  ? contractText.substring(0, 12000) + '\n\n[Document truncated for processing — full review may require multiple passes]'
  : contractText;

// File metadata
const fileName = fileData.name || 'Unknown Contract';
const fileId = fileData.id || '';
const uploadedAt = formatDate(new Date());
const reviewId = 'REV-' + Date.now().toString().slice(-8);

return [{
  json: {
    review_id: reviewId,
    file_name: fileName,
    file_id: fileId,
    contract_text: truncatedText,
    char_count: contractText.length,
    uploaded_at: uploadedAt,
    drive_link: `https://drive.google.com/file/d/${fileId}/view`
  }
}];

// ── Get AI Agent output ─────────────────────────────────
const agentOutput = $input.first().json.output || 
                    $input.first().json.text || 
                    $input.first().json || '';

const contractData = $('Prepare Contract Data').first().json;

// ── Parse the JSON from agent output ───────────────────
let analysis;
try {
  const raw = typeof agentOutput === 'string' ? agentOutput : JSON.stringify(agentOutput);
  const cleaned = raw.replace(/```json|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch(e) {
  // If agent already returned a parsed object
  if (typeof agentOutput === 'object' && agentOutput.contract_type) {
    analysis = agentOutput;
  } else {
    analysis = {
      contract_type: 'Unknown',
      parties: ['Unknown'],
      contract_date: 'Unknown',
      contract_duration: 'Unknown',
      overall_risk_level: 'HIGH',
      risk_score: 0,
      executive_summary: 'Unable to parse AI response. Please review manually.',
      red_flags: [],
      missing_clauses: [],
      key_obligations: [],
      payment_terms: 'Not parsed',
      termination_clauses: 'Not parsed',
      liability_cap: 'Not parsed',
      governing_law: 'Not parsed',
      recommendation: 'MANUAL REVIEW REQUIRED',
      next_steps: 'AI parsing failed. Please review contract manually.'
    };
  }
}

// ── Risk level mapping ──────────────────────────────────
const riskEmoji = {
  'LOW': ':white_check_mark:',
  'MEDIUM': ':warning:',
  'HIGH': ':rotating_light:',
  'CRITICAL': ':sos:',
  'UNKNOWN': ':question:'
};

const riskColor = {
  'LOW': '#22c55e',
  'MEDIUM': '#f59e0b',
  'HIGH': '#ef4444',
  'CRITICAL': '#7f1d1d',
  'UNKNOWN': '#6b7280'
};

const riskLevel = (analysis.overall_risk_level || 'UNKNOWN').toUpperCase();

// ── Build Slack red flags text ──────────────────────────
const redFlagsSlack = (analysis.red_flags || []).map((f, i) =>
  `${i+1}. *${f.clause}* [${f.severity}]\n   ${f.issue}\n   _Fix: ${f.recommendation}_`
).join('\n\n') || 'No red flags identified.';

// ── Build HTML red flags for email ─────────────────────
const redFlagsHtml = (analysis.red_flags || []).map(f => {
  const c = f.severity === 'HIGH' || f.severity === 'CRITICAL'
    ? '#dc2626' : f.severity === 'MEDIUM' ? '#d97706' : '#16a34a';
  return `<tr>
    <td style="padding:9px;border-bottom:1px solid #f0f0f0"><strong>${f.clause}</strong></td>
    <td style="padding:9px;border-bottom:1px solid #f0f0f0;color:#444">${f.issue}</td>
    <td style="padding:9px;border-bottom:1px solid #f0f0f0;color:${c};font-weight:bold;white-space:nowrap">${f.severity}</td>
    <td style="padding:9px;border-bottom:1px solid #f0f0f0;color:#555;font-size:12px">${f.recommendation}</td>
  </tr>`;
}).join('') || '<tr><td colspan="4" style="padding:10px;color:#555">No red flags identified.</td></tr>';

// ── Build HTML missing clauses ──────────────────────────
const missingHtml = (analysis.missing_clauses || []).map(m =>
  `<li style="margin-bottom:8px"><strong>${m.clause}</strong> — ${m.why_important}</li>`
).join('') || '<li style="color:#555">No missing clauses identified.</li>';

// ── Build HTML obligations ──────────────────────────────
const obligationsHtml = (analysis.key_obligations || []).map(o =>
  `<tr>
    <td style="padding:8px;border-bottom:1px solid #f0f0f0"><strong>${o.party}</strong></td>
    <td style="padding:8px;border-bottom:1px solid #f0f0f0;color:#444">${o.obligation}</td>
  </tr>`
).join('') || '<tr><td colspan="2" style="padding:8px;color:#555">No obligations identified.</td></tr>';

// ── Recommendation badge color ──────────────────────────
const recColor = analysis.recommendation === 'APPROVE'
  ? '#16a34a'
  : analysis.recommendation === 'APPROVE WITH CHANGES'
  ? '#d97706' : '#dc2626';

// ── Parties as readable string ──────────────────────────
const partiesText = Array.isArray(analysis.parties)
  ? analysis.parties.join(' & ')
  : (analysis.parties || 'Unknown');

return [{
  json: {
    // Contract metadata
    review_id:              contractData.review_id || 'REV-000000',
    file_name:              contractData.file_name || 'Unknown',
    file_id:                contractData.file_id || '',
    drive_link:             contractData.drive_link || '',
    uploaded_at:            contractData.uploaded_at || '',

    // AI analysis fields
    contract_type:          analysis.contract_type || 'Unknown',
    parties_text:           partiesText,
    contract_date:          analysis.contract_date || 'Unknown',
    contract_duration:      analysis.contract_duration || 'Unknown',
    overall_risk_level:     riskLevel,
    risk_score:             analysis.risk_score || 0,
    executive_summary:      analysis.executive_summary || '',
    payment_terms:          analysis.payment_terms || 'Not specified',
    termination_clauses:    analysis.termination_clauses || 'Not specified',
    liability_cap:          analysis.liability_cap || 'Not specified',
    governing_law:          analysis.governing_law || 'Not specified',
    recommendation:         analysis.recommendation || 'MANUAL REVIEW REQUIRED',
    next_steps:             analysis.next_steps || '',
    red_flags_count:        (analysis.red_flags || []).length,
    missing_clauses_count:  (analysis.missing_clauses || []).length,

    // Formatted outputs
    risk_emoji:             riskEmoji[riskLevel] || ':question:',
    risk_color:             riskColor[riskLevel] || '#6b7280',
    recommendation_color:   recColor,
    red_flags_slack:        redFlagsSlack,
    red_flags_html:         redFlagsHtml,
    missing_clauses_html:   missingHtml,
    obligations_html:       obligationsHtml
  }
}];

